// Sky gradient - dawn sky
const SKY_TOP = '#1a2a4a';
const SKY_BOTTOM = '#3a5a7a';
const SKY_STEPS = 20;
const SKY_Y = 400;

// Draw sky gradient
for (let y = 0; y < SKY_STEPS; y++) {
    const t = y / SKY_STEPS;
    const r = SKY_TOP[0] + (SKY_BOTTOM[0] - SKY_TOP[0]) * t;
    const g = SKY_TOP[1] + (SKY_BOTTOM[1] - SKY_TOP[1]) * t;
    const b = SKY_TOP[2] + (SKY_BOTTOM[2] - SKY_TOP[2]) * t;
    ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
    ctx.fillRect(0, y, W, 1);
}

