// Trees - sparse but dense
const TREE_HEIGHT = 120;
const TREE_WIDTH = 40;
const TREE_SHADE = '#1a3a1a';

// Draw trees
for (let i = 0; i < 30; i++) {
    const x = Math.random() * GROUND_WIDTH;
    const y = SKY_Y + GROUND_HEIGHT - TREE_HEIGHT;

    // Tree trunk
    ctx.fillStyle = TREE_SHADE;
    ctx.fillRect(x - 4, y, 8, TREE_HEIGHT);

    // Tree top
    ctx.fillStyle = '#3a5a3a';
    ctx.beginPath();
    ctx.moveTo(x - TREE_WIDTH/2, y);
    ctx.lineTo(x - TREE_WIDTH/2, y - TREE_HEIGHT);
    ctx.lineTo(x + TREE_WIDTH/2, y);
    ctx.closePath();
    ctx.fill();

    // Add some leaves
    ctx.fillStyle = '#2aa198';
    ctx.beginPath();
    ctx.moveTo(x - TREE_WIDTH/2, y);
    ctx.lineTo(x - TREE_WIDTH/2 + 5, y - TREE_HEIGHT);
    ctx.lineTo(x + TREE_WIDTH/2 - 5, y);
    ctx.closePath();
    ctx.fill();
}

