// Sunflower details
function drawSunflower(stalk) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(stalk.x, stalk.y, 10, 150);

    // Leaves
    ctx.fillStyle = '#32CD32';
    ctx.beginPath();
    ctx.moveTo(stalk.x - 15, stalk.y + 150);
    ctx.lineTo(stalk.x + 15, stalk.y + 150);
    ctx.lineTo(stalk.x, stalk.y + 180);
    ctx.closePath();
    ctx.fill();

    // Center
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(stalk.x + 5, stalk.y + 150, 20, 0, Math.PI * 2);
    ctx.fill();

    // Petals
    ctx.fillStyle = '#FF69B4';
    for (let j = 0; j < 8; j++) {
        const angle = (j / 8) * Math.PI * 2;
        const x = stalk.x + 5 + Math.cos(angle) * 25;
        const y = stalk.y + 150 + Math.sin(angle) * 25;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle + Math.PI/4) * 15, y + Math.sin(angle + Math.PI/4) * 15);
        ctx.lineTo(x + Math.cos(angle - Math.PI/4) * 15, y + Math.sin(angle - Math.PI/4) * 15);
        ctx.closePath();
        ctx.fill();
    }
}

// Draw all sunflowers
