// Cool tones palette for a fractal spiral
const SKY = '#0c1445';
const GROUND = '#1a3a6a';
const ACCENT = '#4a90e2';
const SHADOW = '#0a2c5a';
const HIGHLIGHT = '#4a90e2';

// Draw background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral with cool tones
function drawSpiral(x, y, size, level) {
    if (level > 0) {
        // Draw spiral arms
        ctx.fillStyle = SHADOW;
        ctx.fillRect(x, y, size, size);

        // Draw center highlight
        ctx.fillStyle = HIGHLIGHT;
        ctx.fillRect(x + size/4, y + size/4, size/2, size/2);

        // Recursive draw for spiral arms
        drawSpiral(x - size/4, y + size/4, size/2, level - 1);
        drawSpiral(x + size/4, y + size/4, size/2, level - 1);
        drawSpiral(x + size/4, y - size/4, size/2, level - 1);
        drawSpiral(x - size/4, y - size/4, size/2, level - 1);
    }
}

