// Jellyfish body
const cx = 400;
const cy = 300;
const radius = 60;

// Main body
ctx.fillStyle = '#ffcc99';
ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fill();

// Tentacles
ctx.fillStyle = '#ffbb66';
for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x1 = cx + Math.cos(angle) * radius;
    const y1 = cy + Math.sin(angle) * radius;

    const length = 80 + Math.sin(i) * 20;
    const x2 = cx + Math.cos(angle) * (radius + length);
    const y2 = cy + Math.sin(angle) * (radius + length);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    // Tentacle details
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 + Math.sin(angle) * 10, y2 + Math.cos(angle) * 10);
    ctx.stroke();
}

// Glow effect
const gradient = ctx.createRadialGradient(
    cx, cy, radius,
    cx, cy, radius * 1.5
);
gradient.addColorStop(0, 'rgba(255, 204, 153, 0.3)');
gradient.addColorStop(1, 'rgba(255, 204, 153, 0)');
ctx.fillStyle = gradient;
ctx.beginPath();
ctx.arc(cx, cy, radius * 1.2, 0, Math.PI * 2);
ctx.fill();

